document.addEventListener('DOMContentLoaded', function() {
    // --- QR CODE SCANNER SCRIPT (MODIFIED) ---

    function onScanSuccess(decodedText, decodedResult) {
        // Handle the scanned code (which is a URL)
        console.log(`Scan result: ${decodedText}`);

        // Stop scanning
        html5Qrcode.stop().then(ignore => {
            // Redirect to the URL
            window.location.href = decodedText;
        }).catch(err => {
            console.error("Failed to stop scanner", err);
            window.location.href = decodedText; // Redirect anyway
        });
    }

    function onScanFailure(error) {
        // This will fire continuously, which is normal.
        // console.warn(`Scan failure: ${error}`);
    }

    try {
        var html5Qrcode = new Html5Qrcode("qr-reader");

        // --- NEW DYNAMIC CONFIG ---
        // This config is more robust for different screen/camera sizes.
        // It creates a scanning box that is 70% of the smaller dimension (width or height).
        const qrboxFunction = (viewfinderWidth, viewfinderHeight) => {
            let minEdgePercentage = 0.7; // 70%
            let minEdgeSize = Math.min(viewfinderWidth, viewfinderHeight);
            let qrboxSize = Math.floor(minEdgeSize * minEdgePercentage);
            return {
                width: qrboxSize,
                height: qrboxSize
            };
        }

        const config = { 
            fps: 15, // Increased from 10 for slightly faster scanning
            qrbox: qrboxFunction, // Use the dynamic function
            /* Experimental setting for focus, uncomment if still having issues
               videoConstraints: {
                   focusMode: "continuous"
               }
            */
        };
        // --- END NEW CONFIG ---

        // Try to start the environment-facing camera (back camera)
        html5Qrcode.start({ facingMode: "environment" }, config, onScanSuccess, onScanFailure)
            .catch(err => {
                // If back camera fails, try the user-facing camera (front camera)
                console.warn("Environment camera failed, trying user camera.", err);
                html5Qrcode.start({ facingMode: "user" }, config, onScanSuccess, onScanFailure)
                    .catch(err2 => {
                        console.error("Failed to start any camera.", err2);
                        document.getElementById('qr-reader').innerHTML = 
                            '<p style="color: red; padding: 20px;">Could not start camera. Please ensure permissions are granted.</p>';
                    });
            });
    } catch (ex) {
        console.error("Error initializing QR Scanner", ex);
    }
});
